//! Accuracy gate (generated by ~/.local/share/strategy-vault/gate/gen_gate.py from the checked verdicts, 2026-10-12).
//! verified   = the book prints a comparable result and our backtest reproduces it within fixed tolerances.
//! unverified = exact rules, but nothing comparable is printed in the book.
//! withheld   = no results are published (contradicts the book, same-day path dependent, or a fixed amount with no home).
//! allowed    = for rules with fixed point/dollar amounts, the only tickers where those amounts mean what the book meant.
//! clamp_open = rule fills at the open: on SPX/NDX/DJI results start where the index opens are real (stale before then).
pub struct G { pub id: &'static str, pub verdict: &'static str, pub reason: &'static str, pub allowed: Option<&'static [&'static str]>, pub clamp_open: bool, pub book: &'static str, pub ours: &'static str }
/// US index and ETF tickers (us_data.csv): the home of fixed USD/point amounts read literally ($ / BigPointValue 1 = points, #69).
/// US single stocks are not listed: their prices are split-adjusted, so a fixed amount is not the book's (#166).
pub const US_INDEX_ETF: &[&str] = &["SPX", "NDX", "DJI", "SPY", "QQQ", "IWM", "DIA", "MDY", "SMH", "AGG", "EEM", "EFA", "EPP", "EWA", "EWC", "EWD", "EWG", "EWH",
    "EWI", "EWJ", "EWK", "EWL", "EWM", "EWN", "EWO", "EWP", "EWQ", "EWS", "EWT", "EWU", "EWW", "EWY", "EWZ", "EZA", "EZU", "FXI", "GLD", "IEF", "IEI", "LQD",
    "SHY", "TLH", "TLT", "VNQ", "XLB", "XLE", "XLF", "XLI", "XLK", "XLP", "XLU", "XLV", "XLY"];
/// Lane K36 (decisions #193, #195, #196): rules whose fixed amount is part of the rule. Their `allowed` list holds even where the
/// open-all / VIX India routing would otherwise run them everywhere (readiness::check).
pub const HOME_ONLY: &[&str] = &["pbuel_rsi_pr", "scdshark_32", "sctoombs_stoch20", "wtdtt_mist1", "wtdtt_mist2", "wtdtt_mist3",
    "wtdtt_mist4", "wtdtt_mist5", "wtdtt_mist6", "ws5_double_window", "ws5_gap_window_eod", "ws5_gap_window_intraday", "ws5_hanging_window",
    "ws5_momentum_windows_any", "ws5_non_vix_market_timing", "ws5_outside_window", "ws5_single_window", "ws5_vix_iii_reversal", "ws5_weekly_windows"];
pub fn home_only(id: &str) -> bool { HOME_ONLY.contains(&id) }
/// R4 #376 (23 Nov 2026, lane I2): rules withheld only because the US book windows differ from the printed tables. On Indian runs they are
/// published (the gate text records the 0-mismatch independent reference on the Indian runs); US runs stay withheld.
pub const INDIA_REOPEN_376: &[&str] = &["strtw_bj_bj", "strtw_dbs1b", "strtw_meander_bj_ma", "strtw_meander_wk_x", "ss_study_fresh_adx_buy", "ss_study_fresh_adx_sell", "spmt_rsi2_4", "spmt_rsi_1", "sglr_dow_ma200_band", "putg_narrow_range", "lkqts_dom1", "kftsm_4_9_18", "mjlbb_mae3_50", "masmt_vakkur_may_oct", "jbssf_sp_jan", "jbhsms_sp_0226", "jbhsms_sp_0301", "rwmts_env_fade", "rwmts_ma2x", "rwmts_rsi_ext", "rwmts_stoch_cci"];
pub fn india_reopened(id: &str) -> bool { INDIA_REOPEN_376.contains(&id) }
/// Of those, index-timing / index-only rules (#364): re-opened on the Indian indices their independent reference covers, never on Indian stocks.
pub const INDIA_REOPEN_376_INDEX_ONLY: &[&str] = &["ss_study_fresh_adx_buy", "ss_study_fresh_adx_sell", "spmt_rsi2_4", "spmt_rsi_1", "sglr_dow_ma200_band", "putg_narrow_range", "lkqts_dom1", "kftsm_4_9_18", "mjlbb_mae3_50", "masmt_vakkur_may_oct", "jbssf_sp_jan", "jbhsms_sp_0226", "jbhsms_sp_0301"];
/// The Indian index tickers the reference covers for an index-only id.
fn index_scope(id: &str) -> &'static [&'static str] { if id.starts_with("ss_study_fresh_adx") || id.starts_with("spmt_rsi") || id == "kftsm_4_9_18" || id.starts_with("mjlbb_") || id == "masmt_vakkur_may_oct" || id == "jbssf_sp_jan" || id.starts_with("jbhsms_sp_") { &["NIFTY 50", "NIFTYBANK", "NIFTYMIDCAP100"] } else { &["NIFTY 50", "NIFTYBANK"] } }
/// Whether the withhold is lifted for an Indian run (`native_stock` = an actual stock, `ticker` = the run's instrument).
pub fn india_reopened_on(id: &str, native_stock: bool, ticker: &str) -> bool { india_reopened(id) && (!INDIA_REOPEN_376_INDEX_ONLY.contains(&id) || (!native_stock && index_scope(id).contains(&ticker))) }
